// <work-doc> — renders an org/markdown document directly from its source. The
// reinvention: the document IS its source (preview ≡ source) — there is no
// separate document model, so the same bytes an agent or cursor edits are what
// renders. Source comes from a `src` attr (a URL or inline) or the element's
// own inner text.
//
// Standalone fidelity: a dependency-free markdown + basic-org renderer
// (./render.js) — headings, lists, code, emphasis, links, tables, blockquotes,
// rules, checkboxes, and org TODO pills + tags. For FULL org fidelity (property
// drawers, footnotes, citations, #+EXEC component blocks, exact orgize parity)
// a wired Host routes rendering through the OQL kernel (oql.wasm) — the same
// pipeline desktop/src/lib/org-renderer uses; this element reaches it via
// `this.host` when the `kernel` capability is available, and falls back to the
// standalone renderer otherwise.
//
// Live cells: fenced ```sql / ```polars / ```py / ```js / ```chart blocks (and
// the org #+begin_src equivalents) become <work-doc-cell> elements — first-class
// computed blocks, the docs-domain differentiator.
//
// Cross-element: emits `work-doc:rendered` with the parsed outline, so a sibling
// <work-doc-outline for="…"> stays auto-synced.
import { WbElement, html, css, define } from "../../core/element.js";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import { renderDoc, parseOutline } from "./render.js";
import { PROSE_CSS } from "./prose.js";
import "./wb-doc-cell.js";

let _cellSeq = 0;

export class WbDoc extends WbElement {
  static props = ["src", "format"];

  static styles = css`
    :host { display: block; }
    .doc { max-width: 76ch; margin: 0 auto; }
    .loading, .error { color: var(--work-fg-muted); font-family: var(--work-font); padding: var(--work-space-4); }
    .error { color: var(--work-err); }
    ${PROSE_CSS}
  `;

  connectedCallback() {
    if (this._source == null) this._source = this.attr("src") ? null : this.textContent;
    super.connectedCallback();
    if (this.attr("src")) this._loadSrc(this.attr("src"));
  }

  async _loadSrc(url) {
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`${res.status} ${url}`);
      // docx is an I/O adapter on top of the org/markdown source: a .docx src is
      // imported to that source, then rendered by the normal path. Detect by the
      // URL extension OR the ZIP container magic (PK…) so a docx served without a
      // .docx suffix still routes correctly.
      const buf = await res.arrayBuffer();
      const isDocx = /\.docx(\?|#|$)/i.test(url) || (await this._isDocxBuf(buf));
      this._source = isDocx ? await this._importDocx(buf) : new TextDecoder().decode(buf);
      this.requestUpdate();
    } catch (e) {
      this._error = String(e.message || e);
      this.requestUpdate();
    }
  }

  async _isDocxBuf(buf) {
    const { looksLikeDocx } = await import("./docx-io.js");
    return looksLikeDocx(buf);
  }

  async _importDocx(buf) {
    const { importDocx } = await import("./docx-io.js");
    return importDocx(buf);
  }

  /**
   * Set the document from a .docx ArrayBuffer (import adapter). Renders the result
   * as org/markdown through the normal path. Emits `work-doc-export` on completion
   * is NOT this path — see export() — but a failed import surfaces a clear error.
   * @param {ArrayBuffer} buf
   */
  async importDocxBuffer(buf) {
    try {
      this._source = await this._importDocx(buf);
      this._error = null;
    } catch (e) {
      this._error = String(e.message || e);
    }
    this.requestUpdate();
    return this._source;
  }

  /**
   * Export the current document. format "docx": when a runtime is docked, route
   * through the Host (pandoc.wasm, max fidelity); otherwise the floor `exportDocx`
   * builds the .docx Blob in-browser. Emits `work-doc-export {format, ok}`. Returns
   * the Blob (or null on failure).
   * @param {"docx"} [format]
   * @returns {Promise<Blob|null>}
   */
  async export(format = "docx") {
    if (format !== "docx") {
      this.dispatchEvent(new CustomEvent("work-doc-export", { bubbles: true, composed: true, detail: { format, ok: false, error: `unsupported format ${format}` } }));
      return null;
    }
    try {
      let blob;
      // Host tier (pandoc over the Dock) when docked — kept optional; the floor is
      // the always-available default and the only path required to wire here.
      if (this.host && this.host.available("runtime") && this.host.runtimeUrl) {
        blob = await this._exportViaHost(this.source);
      }
      if (!blob) {
        const { exportDocx } = await import("./docx-io.js");
        blob = await exportDocx(this.source);
      }
      this.dispatchEvent(new CustomEvent("work-doc-export", { bubbles: true, composed: true, detail: { format, ok: true } }));
      return blob;
    } catch (e) {
      this.dispatchEvent(new CustomEvent("work-doc-export", { bubbles: true, composed: true, detail: { format, ok: false, error: String(e.message || e) } }));
      return null;
    }
  }

  async _exportViaHost(source) {
    try {
      const r = await this.host.request("/api/doc/export", { body: { format: "docx", source } });
      if (r && r.blobBase64) {
        const bin = atob(r.blobBase64);
        const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
        return new Blob([bytes], { type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document" });
      }
    } catch { /* fall through to the floor */ }
    return null;
  }

  /** The document source string (the artifact's truth). */
  get source() { return this._source || ""; }
  set source(v) { this._source = v; this._error = null; this.requestUpdate(); }

  /** The heading outline — consumed by <work-doc-outline>. */
  get outline() { return parseOutline(this.source); }

  render() {
    if (this._error) return html`<div class="error">Could not load document: ${this._error}</div>`;
    if (this._source == null) return html`<div class="loading">Loading…</div>`;

    // Pull live-cell blocks out into placeholders, render prose, then re-insert
    // real <work-doc-cell> elements after the DOM is updated (so their own shadow
    // DOM mounts and computes).
    this._pendingCells = [];
    const body = renderDoc(this._source, {
      onCell: ({ lang, code }) => {
        const id = `workcell-${++_cellSeq}`;
        this._pendingCells.push({ id, lang, code });
        return `<div data-cell="${id}"></div>`;
      },
    });
    // body is trusted output of OUR renderer (escaped at the source — see render.js).
    return html`<article class="doc prose">${unsafeHTML(body)}</article>`;
  }

  updated() {
    // mount the deferred live cells
    for (const c of this._pendingCells || []) {
      const slot = this.shadowRoot.querySelector(`[data-cell="${c.id}"]`);
      if (!slot) continue;
      const cell = document.createElement("work-doc-cell");
      cell.setAttribute("lang", c.lang);
      cell.textContent = c.code;
      slot.replaceWith(cell);
    }
    this._pendingCells = [];
    // announce the outline for siblings (e.g. <work-doc-outline>)
    this.dispatchEvent(new CustomEvent("work-doc:rendered", {
      bubbles: true, composed: true, detail: { outline: this.outline, id: this.id },
    }));
  }
}

define("work-doc", WbDoc);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// docs/prose.js — the shared themed-prose CSS for the docs domain.
//
// A Lit `css` CSSResult (composes into `static styles` via `${PROSE_CSS}`).
// Token-only (every value var(--work-*)). Imported by work-doc + work-doc-cell so the
// rendered document and its live cells read as one typeset surface. Mirrors the
// visual contract of the desktop org-renderer (desktop/src/lib/org-renderer/
// org.css) but expressed purely from the workponents token set.

import { css } from "../../core/element.js";

export const PROSE_CSS = css`
  .prose {
    font-family: var(--work-font);
    font-size: var(--work-text);
    line-height: 1.7;
    color: var(--work-fg);
  }
  .prose > :first-child { margin-top: 0; }
  .prose > :last-child { margin-bottom: 0; }

  .prose h1, .prose h2, .prose h3, .prose h4, .prose h5, .prose h6 {
    font-family: var(--work-font-display, var(--work-font));
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: -0.01em;
    color: var(--work-fg);
    scroll-margin-top: var(--work-space-5);
    display: flex; align-items: center; flex-wrap: wrap; gap: var(--work-space-2);
  }
  .prose h1 { font-size: 1.7em; margin: 1.6em 0 0.6em; padding-bottom: var(--work-space-2); border-bottom: 1px solid var(--work-border); }
  .prose h2 { font-size: 1.35em; margin: 1.5em 0 0.5em; }
  .prose h3 { font-size: 1.12em; margin: 1.3em 0 0.4em; }
  .prose h4 { font-size: 1em; margin: 1.1em 0 0.35em; color: var(--work-fg-muted); }
  .prose p { margin: 0.85em 0; }

  .prose a {
    color: var(--work-brand);
    text-decoration: none;
    border-bottom: 1px solid color-mix(in srgb, var(--work-brand) 45%, transparent);
  }
  .prose a:hover { border-bottom-color: var(--work-brand); }

  .prose ul, .prose ol { margin: 0.7em 0; padding-left: 1.4em; }
  .prose li { margin: 0.25em 0; }
  .prose li.doc-task { list-style: none; margin-left: -1.4em; display: flex; align-items: baseline; gap: var(--work-space-2); }
  .prose li.doc-task input { accent-color: var(--work-brand); }

  .prose code {
    font-family: var(--work-font-mono);
    font-size: 0.86em;
    padding: 0.1em 0.4em;
    border-radius: var(--work-radius-sm);
    background: var(--work-surface-soft);
    color: var(--work-fg);
  }
  .prose pre {
    margin: 1em 0;
    padding: var(--work-space-4);
    border-radius: var(--work-radius);
    background: var(--work-surface-soft);
    border: 1px solid var(--work-border);
    overflow-x: auto;
  }
  .prose pre code { background: none; padding: 0; font-size: var(--work-text-sm); line-height: 1.6; }

  .prose blockquote {
    margin: 1em 0;
    padding: var(--work-space-2) var(--work-space-4);
    border-left: 3px solid var(--work-brand);
    background: var(--work-brand-soft);
    border-radius: 0 var(--work-radius-sm) var(--work-radius-sm) 0;
    color: var(--work-fg-muted);
  }

  .prose hr { border: none; border-top: 1px solid var(--work-border); margin: 1.8em 0; }

  .prose table {
    width: 100%;
    border-collapse: collapse;
    margin: 1em 0;
    font-size: var(--work-text-sm);
  }
  .prose th, .prose td {
    text-align: left;
    padding: var(--work-space-2) var(--work-space-3);
    border-bottom: 1px solid var(--work-border);
  }
  .prose th { font-weight: 600; color: var(--work-fg-muted); border-bottom-color: var(--work-border-strong); }
  .prose tbody tr:hover { background: var(--work-surface-soft); }

  /* org TODO pills + tag chips on headings */
  .doc-state {
    font-family: var(--work-font-mono);
    font-size: 0.62em; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
    padding: 0.2em 0.55em; border-radius: var(--work-radius-pill);
    background: var(--work-surface-soft); color: var(--work-fg-muted);
    border: 1px solid var(--work-border);
  }
  .doc-state-done { background: var(--work-brand-soft); color: var(--work-ok); border-color: transparent; }
  .doc-state-todo, .doc-state-next { background: var(--work-brand-soft); color: var(--work-brand); border-color: transparent; }
  .doc-state-wait, .doc-state-blocked { color: var(--work-warn); }
  .doc-state-cancelled { color: var(--work-err); text-decoration: line-through; }
  .doc-tags { display: inline-flex; gap: var(--work-space-1); }
  .doc-tag {
    font-family: var(--work-font-mono); font-size: 0.6em; font-weight: 600;
    padding: 0.15em 0.5em; border-radius: var(--work-radius-pill);
    background: var(--work-surface-soft); color: var(--work-fg-subtle);
  }
`;

// docs/render.js — the standalone markdown + basic-org → HTML renderer.
//
// The reinvention: the document IS its source, rendered directly (preview ≡
// source). For the seed this is a small dependency-free renderer covering the
// common block + inline grammar shared by markdown and org: headings, lists,
// code, emphasis, links, tables, rules, blockquotes, checkboxes, org TODO
// pills + tags. It is deliberately a SUBSET — for full org fidelity (property
// drawers, #+EXEC cells, citations, footnotes) an element reaches the OQL
// kernel (oql.wasm) through `this.host` (see the note in work-doc.js). The
// visual contract is kept aligned with the desktop org-renderer
// (desktop/src/lib/org-renderer/*).

export function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// --- inline grammar (markdown + org emphasis, code, links) ----------------
function inline(text) {
  let s = escapeHtml(text);
  // inline code: `code` (md), =code= / ~code~ (org verbatim)
  s = s.replace(/`([^`]+)`/g, (_m, c) => `<code>${c}</code>`);
  s = s.replace(/(^|[\s(])=([^=\s][^=]*?)=(?=[\s).,;:]|$)/g, (_m, p, c) => `${p}<code>${c}</code>`);
  s = s.replace(/(^|[\s(])~([^~\s][^~]*?)~(?=[\s).,;:]|$)/g, (_m, p, c) => `${p}<code>${c}</code>`);
  // links: [text](url) markdown, [[url][text]] / [[url]] org
  s = s.replace(/\[\[([^\]]+)\]\[([^\]]+)\]\]/g, (_m, url, t) => `<a href="${url}">${t}</a>`);
  s = s.replace(/\[\[([^\]]+)\]\]/g, (_m, url) => `<a href="${url}">${url}</a>`);
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t, url) => `<a href="${url}">${t}</a>`);
  // bold: **md** then *org single-star*
  s = s.replace(/\*\*([^*]+)\*\*/g, (_m, t) => `<strong>${t}</strong>`);
  s = s.replace(/(^|[\s(])\*([^*\s][^*]*?)\*(?=[\s).,;:]|$)/g, (_m, p, t) => `${p}<strong>${t}</strong>`);
  // italic: /org/ then _md/org_
  s = s.replace(/(^|[\s(])\/([^/\s][^/]*?)\/(?=[\s).,;:]|$)/g, (_m, p, t) => `${p}<em>${t}</em>`);
  s = s.replace(/(^|[\s(])_([^_\s][^_]*?)_(?=[\s).,;:]|$)/g, (_m, p, t) => `${p}<em>${t}</em>`);
  return s;
}

function tableCells(line) {
  return line
    .replace(/^\s*\|/, "")
    .replace(/\|\s*$/, "")
    .split("|")
    .map((c) => c.trim());
}

function isTableSep(line) {
  return /^\s*\|?[\s:|+-]+\|[\s:|+-]*$/.test(line) && /-/.test(line);
}

// A heading in either grammar; returns {level, text} or null.
function headingOf(line) {
  let m = line.match(/^(#{1,6})\s+(.*)$/); // markdown ATX
  if (m) return { level: m[1].length, text: m[2].trim() };
  m = line.match(/^(\*{1,6})\s+(.*)$/); // org headline
  if (m) return { level: m[1].length, text: m[2].trim() };
  return null;
}

const TODO_KW = /^(TODO|NEXT|IN_PROGRESS|WAIT|DONE|CANCELLED|BLOCKED)\s+/;

function slugify(text) {
  return String(text)
    .toLowerCase()
    .replace(/<[^>]+>/g, "")
    .replace(/[^\w\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .slice(0, 64);
}

// Split a heading's raw text into { state, tags, text }.
function splitHeading(raw) {
  let text = raw;
  let tags = [];
  const tagm = text.match(/\s+:([\w@:-]+):\s*$/);
  if (tagm) { tags = tagm[1].split(":").filter(Boolean); text = text.slice(0, tagm.index).trim(); }
  let state = null;
  const km = text.match(TODO_KW);
  if (km) { state = km[1]; text = text.slice(km[0].length); }
  return { state, tags, text };
}

// The heading outline (used by work-doc-outline + work-doc cross-sync).
export function parseOutline(src) {
  const out = [];
  let inFence = false;
  for (const raw of String(src).replace(/\r\n?/g, "\n").split("\n")) {
    const t = raw.trim();
    if (/^```/.test(t) || /^#\+(begin|end)_src/i.test(t)) { inFence = !inFence; continue; }
    if (inFence) continue;
    const h = headingOf(raw);
    if (!h) continue;
    const { state, text } = splitHeading(h.text);
    out.push({ level: h.level, text, state, id: slugify(text) });
  }
  return out;
}

// The core: markdown/org source → HTML string. Fenced/src blocks whose lang is
// a known compute language are handed to `onCell` so work-doc can mount a live
// <work-doc-cell>; everything else renders as a <pre>.
export function renderDoc(src, { onCell } = {}) {
  const lines = String(src).replace(/\r\n?/g, "\n").split("\n");
  const html = [];
  let i = 0;
  let listStack = []; // 'ul' | 'ol'
  let para = [];

  const closeList = () => { while (listStack.length) html.push(`</${listStack.pop()}>`); };
  const flushPara = () => {
    if (para.length) { html.push(`<p>${inline(para.join(" "))}</p>`); para = []; }
  };
  const breakBlocks = () => { flushPara(); closeList(); };

  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();

    // org export/meta lines (#+TITLE:, #+AUTHOR:, …) — skip, but NOT src blocks
    if (/^#\+/i.test(trimmed) && !/^#\+(begin|end)_src/i.test(trimmed)) { i++; continue; }

    // fenced code / org src block (possibly a live cell)
    const fence = trimmed.match(/^```(\w+)?/) || trimmed.match(/^#\+begin_src\s*(\w+)?/i);
    if (fence) {
      breakBlocks();
      const lang = (fence[1] || "").toLowerCase();
      const closeRe = trimmed.startsWith("```") ? /^```\s*$/ : /^#\+end_src/i;
      const code = [];
      i++;
      while (i < lines.length && !closeRe.test(lines[i].trim())) { code.push(lines[i]); i++; }
      i++; // consume closing fence
      const body = code.join("\n");
      const isCell = onCell && /^(sql|polars|duckdb|py|python|js|chart)$/.test(lang);
      if (isCell) html.push(onCell({ lang, code: body }));
      else html.push(`<pre data-lang="${escapeHtml(lang)}"><code>${escapeHtml(body)}</code></pre>`);
      continue;
    }

    // headings
    const h = headingOf(line);
    if (h) {
      breakBlocks();
      const { state, tags, text } = splitHeading(h.text);
      const lvl = Math.min(6, h.level);
      const id = slugify(text);
      const pill = state
        ? `<span class="doc-state doc-state-${state.toLowerCase()}">${escapeHtml(state.replace("_", " "))}</span>`
        : "";
      const tagHtml = tags.length
        ? `<span class="doc-tags">${tags.map((tg) => `<span class="doc-tag">${escapeHtml(tg)}</span>`).join("")}</span>`
        : "";
      html.push(`<h${lvl} id="${id}">${pill}${inline(text)}${tagHtml}</h${lvl}>`);
      i++;
      continue;
    }

    // horizontal rule
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) { breakBlocks(); html.push("<hr />"); i++; continue; }

    // blockquote
    if (/^>\s?/.test(trimmed)) {
      breakBlocks();
      const quote = [];
      while (i < lines.length && /^>\s?/.test(lines[i].trim())) {
        quote.push(lines[i].trim().replace(/^>\s?/, "")); i++;
      }
      html.push(`<blockquote>${inline(quote.join(" "))}</blockquote>`);
      continue;
    }

    // table
    if (/^\s*\|/.test(line) && line.includes("|")) {
      breakBlocks();
      const rows = [];
      while (i < lines.length && /^\s*\|/.test(lines[i])) { rows.push(lines[i]); i++; }
      const hasSep = rows.length > 1 && isTableSep(rows[1]);
      const headRow = hasSep ? rows[0] : null;
      const bodyRows = hasSep ? rows.slice(2) : rows;
      let t = "<table>";
      if (headRow) t += "<thead><tr>" + tableCells(headRow).map((c) => `<th>${inline(c)}</th>`).join("") + "</tr></thead>";
      t += "<tbody>";
      for (const r of bodyRows) {
        if (isTableSep(r)) continue; // org table rule "|---|"
        t += "<tr>" + tableCells(r).map((c) => `<td>${inline(c)}</td>`).join("") + "</tr>";
      }
      t += "</tbody></table>";
      html.push(t);
      continue;
    }

    // lists (markdown - * + and ordered 1.) — single level for the seed
    const ulm = line.match(/^(\s*)[-*+]\s+(.*)$/);
    const olm = line.match(/^(\s*)\d+[.)]\s+(.*)$/);
    if (ulm || olm) {
      flushPara();
      const want = olm ? "ol" : "ul";
      if (listStack[listStack.length - 1] !== want) { closeList(); listStack = [want]; html.push(`<${want}>`); }
      const content = ulm ? ulm[2] : olm[2];
      const cb = content.match(/^\[([ xX-])\]\s+(.*)$/);
      if (cb) {
        const checked = /[xX]/.test(cb[1]) ? " checked" : "";
        html.push(`<li class="doc-task"><input type="checkbox" disabled${checked} />${inline(cb[2])}</li>`);
      } else {
        html.push(`<li>${inline(content)}</li>`);
      }
      i++;
      continue;
    }

    // blank line ends a paragraph / list
    if (trimmed === "") { breakBlocks(); i++; continue; }

    // default: accumulate paragraph text
    para.push(trimmed);
    i++;
  }

  breakBlocks();
  return html.join("\n");
}

// <work-doc-cell> — a live computed block inside a document. THE differentiator:
// the block that renders the data also computes it. A cell carries its query as
// source (preview ≡ source); it reaches an engine through the Dock seam
// (`this.host`) — DuckDB-wasm / Polars / the OQL kernel resolved local | runtime
// | kernel per platform-model. When no engine is reachable it degrades cleanly
// to a "computed" preview with sample output (the same shape a real run returns),
// so the document is never broken by an absent capability.
//
// Usage (standalone): <work-doc-cell lang="sql">SELECT region, sum(rev) ...</work-doc-cell>
// Or, embedded by <work-doc> from a fenced ```sql block in the source.
import { WbElement, html, css, define } from "../../core/element.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";

const VARIANTS = defineVariants({
  // how the result renders
  display: { options: ["table", "metric", "raw"], default: "table" },
  // visual weight of the cell shell
  variant: { options: ["card", "inline"], default: "card" },
});

// The compute language → which capability backs it (declared, Dock-resolved).
const LANG_CAP = {
  sql: "duckdb", duckdb: "duckdb",
  polars: "duckdb",
  py: "kernel", python: "kernel", js: "kernel", chart: "kernel",
};

// Graceful sample output per language — the SHAPE a real run returns, so the
// document reads correctly offline. (The seed's stub; a live host replaces it.)
function sampleResult(lang, code) {
  // A single scalar aggregate with no GROUP BY reads as a metric; anything that
  // groups/selects multiple columns reads as a table.
  const scalar = /\b(count|sum|avg|min|max)\s*\(/i.test(code) && !/group\s+by/i.test(code);
  if (scalar && lang !== "polars") {
    return { kind: "metric", value: "128,402", label: "orders", delta: "+12.4%" };
  }
  return {
    kind: "table",
    columns: ["region", "orders", "revenue"],
    rows: [
      ["North", "4,182", "$612,400"],
      ["South", "3,907", "$548,210"],
      ["EMEA", "2,640", "$501,880"],
      ["APAC", "1,933", "$377,150"],
    ],
  };
}

export class WbDocCell extends WbElement {
  static variants = VARIANTS;
  static props = [...variantAttrs(VARIANTS), "lang", "src", "title", "state"];

  static styles = css`
    :host { display: block; margin: 1.1em 0; }
    .cell { border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); overflow: hidden; box-shadow: var(--work-shadow-sm); }
    :host([variant="inline"]) .cell { border: none; box-shadow: none; background: transparent; }

    .head { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3); border-bottom: 1px solid var(--work-border);
      background: var(--work-surface-soft); font-family: var(--work-font-mono); font-size: var(--work-text-sm); }
    :host([variant="inline"]) .head { background: transparent; padding-left: 0; padding-right: 0; }
    .lang { font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--work-brand); }
    .title { color: var(--work-fg); font-family: var(--work-font); font-weight: 600; }
    .status { margin-left: auto; display: inline-flex; align-items: center; gap: var(--work-space-1);
      font-size: 0.85em; color: var(--work-fg-muted); }
    .dot { width: 7px; height: 7px; border-radius: var(--work-radius-pill); background: var(--work-brand);
      box-shadow: 0 0 0 3px var(--work-brand-soft); }
    .status[data-state="stub"] .dot { background: var(--work-warn); box-shadow: 0 0 0 var(--work-space-3px) var(--work-warn-glow); }
    .status[data-state="error"] .dot { background: var(--work-err); box-shadow: none; }

    .query { margin: 0; padding: var(--work-space-3); font-family: var(--work-font-mono);
      font-size: var(--work-text-sm); line-height: 1.55; color: var(--work-fg-muted);
      background: var(--work-bg); border-bottom: 1px solid var(--work-border); white-space: pre-wrap; word-break: break-word; }
    :host([variant="inline"]) .query { background: var(--work-surface-soft); border-radius: var(--work-radius-sm); border: none; }

    .out { padding: var(--work-space-3); font-family: var(--work-font); }

    table { width: 100%; border-collapse: collapse; font-size: var(--work-text-sm); }
    th, td { text-align: left; padding: var(--work-space-2) var(--work-space-3); border-bottom: 1px solid var(--work-border); }
    th { font-weight: 600; color: var(--work-fg-muted); font-family: var(--work-font-mono); font-size: 0.85em;
      text-transform: uppercase; letter-spacing: 0.04em; }
    tbody tr:last-child td { border-bottom: none; }
    tbody tr:hover { background: var(--work-surface-soft); }
    td:not(:first-child) { font-variant-numeric: tabular-nums; }

    .metric { display: flex; align-items: baseline; gap: var(--work-space-3); }
    .metric .v { font-family: var(--work-font-display, var(--work-font)); font-size: 2.4em; font-weight: 600;
      letter-spacing: -0.02em; color: var(--work-fg); line-height: 1; }
    .metric .l { color: var(--work-fg-muted); font-size: var(--work-text-sm); }
    .metric .d { margin-left: auto; color: var(--work-ok); font-weight: 600; font-size: var(--work-text-sm); }

    .foot { padding: var(--work-space-2) var(--work-space-3); border-top: 1px solid var(--work-border);
      font-size: var(--work-text-sm); color: var(--work-fg-subtle); display: flex; gap: var(--work-space-2); align-items: center; }
    .recompute { cursor: pointer; color: var(--work-brand); border: none; background: none; font: inherit;
      font-family: var(--work-font-mono); padding: 0; }
    .recompute:hover { text-decoration: underline; }
    pre.raw { margin: 0; font-family: var(--work-font-mono); font-size: var(--work-text-sm); }
  `;

  connectedCallback() {
    // Capture inner source ONCE before the base wipes the shadow root; the cell
    // body is its query (composition-as-source).
    if (this._source == null) {
      const inner = this.textContent.trim();
      this._source = this.attr("src") || inner || "";
    }
    super.connectedCallback();
    this._compute();
  }

  async _compute() {
    const lang = (this.attr("lang", "sql") || "sql").toLowerCase();
    const cap = LANG_CAP[lang] || "kernel";
    this._busy = true;
    this._error = null;
    this.requestUpdate();
    try {
      if (this.host.available(cap)) {
        // Live path: ask the runtime/kernel to run the cell. The seam exists; a
        // configured Host routes it. (Endpoint contract: POST /docs/cell.)
        const res = await this.host.request("/docs/cell", { body: { lang, source: this._source } });
        this._result = res && res.result ? res.result : sampleResult(lang, this._source);
        this._live = !!(res && res.result);
      } else {
        this._result = sampleResult(lang, this._source);
        this._live = false;
      }
    } catch (e) {
      this._error = String(e.message || e);
      this._result = sampleResult(lang, this._source);
      this._live = false;
    }
    this._busy = false;
    this.requestUpdate();
  }

  _renderResult() {
    const r = this._result || {};
    const display = this.attr("display") || (r.kind === "metric" ? "metric" : "table");
    if (display === "raw") {
      return html`<pre class="raw">${JSON.stringify(r, null, 2)}</pre>`;
    }
    if (r.kind === "metric" || display === "metric") {
      return html`<div class="metric"><span class="v">${r.value ?? "—"}</span><span class="l">${r.label ?? ""}</span>${r.delta ? html`<span class="d">${r.delta}</span>` : ""}</div>`;
    }
    const cols = r.columns || [];
    const rows = r.rows || [];
    return html`<table><thead><tr>${cols.map((c) => html`<th>${c}</th>`)}</tr></thead><tbody>${rows.map(
      (row) => html`<tr>${row.map((c) => html`<td>${c}</td>`)}</tr>`,
    )}</tbody></table>`;
  }

  render() {
    const lang = (this.attr("lang", "sql") || "sql").toLowerCase();
    const title = this.attr("title");
    const state = this._error ? "error" : this._live ? "live" : "stub";
    const stateText = this._busy ? "computing…" : this._error ? "compute error" : this._live ? "computed live" : "computed (sample)";
    return html`
      <div class="cell">
        <div class="head">
          <span class="lang">${lang}</span>
          ${title ? html`<span class="title">${title}</span>` : ""}
          <span class="status" data-state=${state}><span class="dot"></span>${stateText}</span>
        </div>
        ${this._source ? html`<pre class="query">${this._source}</pre>` : ""}
        <div class="out">${this._busy ? html`<span style="color:var(--work-fg-muted)">running…</span>` : this._renderResult()}</div>
        <div class="foot">
          <button class="recompute" type="button" @click=${this._compute}>recompute</button>
          <span>·</span>
          <span>${this._live ? "engine: " + (LANG_CAP[lang] || "kernel") : "no engine reached — sample shape shown"}</span>
        </div>
      </div>`;
  }
}

define("work-doc-cell", WbDocCell);
